function copyText() {   const textElement = document.getElementById('textToCopy');   const textToCopy = textElement.innerText;   navigator.clipboard.writeText(textToCopy)   .then(() => {      alert('Text copied to clipboard!');   })   .catch(err => {      console.error('Failed to copy text: ', err);      alert('Failed to copy text. Please try again or copy manually.');   });}